local catalog = {
    profile = profile, source = metadata and metadata.source,
    releaseURL = metadata and metadata.releaseURL, archiveSHA256 = metadata and metadata.archiveSHA256,
    count = metadata and metadata.stockCount or 0, pricedCount = metadata and metadata.pricedCount or 0, metadata = metadata,
}
local function ID(itemID)
    if issecretvalue and issecretvalue(itemID) then return end
    local id = tonumber(itemID)
    if id and id > 0 and id % 1 == 0 then return id end
end
function catalog.Has(itemID)
    local id = ID(itemID)
    return id ~= nil and ((prices and prices[id] ~= nil) or (stockOnly and stockOnly[id] == true)) or false
end
function catalog.GetTerms(itemID)
    local id = ID(itemID)
    local raw = id and prices and prices[id]
    if raw then return raw, buyCounts[id] or 1 end
end
function catalog.Get(itemID)
    local raw, count = catalog.GetTerms(itemID)
    return raw and raw / count or nil, profile, catalog.source
end
FluxAuctionRestock.VendorCatalog = catalog
